  function learningHash(id){return id ? `#/learn?path=${encodeURIComponent(id)}` : "#/learn";}
  function learningStepLink(id,path){return `#/theory/${encodeURIComponent(id)}?from=learn&path=${encodeURIComponent(path)}`;}
  function renderPrimer(primer){
    if(!primer)return "";
    return `<section class="learning-primer" aria-label="${esc(primer.title)}"><h4>${esc(primer.title)}</h4>${primer.paragraphs.map((claim,i)=>`${profileClaim(claim)}${i===1&&primer.equation?`<p class="primer-equation">${esc(primer.equation)}</p>`:""}`).join("")}<p class="reviewed">${esc(primer.sourceLocator)}</p>${(primer.sourceLocations||[]).length?`<ul class="primer-locators">${primer.sourceLocations.map(l=>`<li>${esc(sourceById.get(l.sourceId)?.title||l.sourceId)}: <a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.locator)}</a></li>`).join("")}</ul>`:""}</section>`;
  }
  function pathProgress(path,read){
    const marked=new Set(read);
    return {done:path.steps.filter(step=>marked.has(step.theoryId)).length,next:path.steps.find(step=>!marked.has(step.theoryId))||null};
  }
  function renderPathProgress(path,progress){
    const step=progress.next||path.steps[0];
    const action=!progress.next?"Review from start":progress.done?"Continue reading":"Start this path";
    return `<div class="learning-progress"><p>${progress.done} / ${path.steps.length} entries marked read${progress.next?"":" · All entries marked read"}</p><progress value="${progress.done}" max="${path.steps.length}" aria-label="${esc(path.title)} reading progress"></progress><p class="muted">${progress.next?`Next unread: ${esc(byId.get(step.theoryId).name)}`:"Revisit an entry or compare the approaches."}</p><a class="ghost link-button" data-resume-path="${path.id}" href="${learningStepLink(step.theoryId,path.id)}" aria-label="${esc(action+": "+path.title)}">${action}</a></div>`;
  }
  function renderLearningReferences(path){
    const evidence=(path.relatedEvidenceIds||[]).map(id=>evidenceRecords.find(e=>e.id===id)).filter(Boolean);
    const ps=(path.relatedProblemIds||[]).map(id=>problemById.get(id)).filter(Boolean);
    if(!evidence.length&&!ps.length)return "";
    return `<section class="learning-references"><h4>Inspect evidence and open problems</h4><p>These linked records state conditional constraints and what they do not establish.</p><ul>${evidence.map(e=>`<li><a href="#/evidence?search=${encodeURIComponent(e.title)}">${esc(e.title)}</a> · ${esc(e.type)}</li>`).join("")}${ps.map(p=>`<li><a href="${problemHash(p.id)}">${esc(p.name)}</a> · open problem</li>`).join("")}</ul></section>`;
  }
  function renderLearningPaths(){
