  box-shadow:var(--shadow)
}
.controls{padding:16px}
.controls label,.formula-controls label{color:#607684}
.controls input[type=search],.controls select,
.formula-controls input,.formula-controls select,
.comparison-selectors select,.comparison-selectors input,
.research-tools textarea,#workspaceSearch,.evidence-controls select{
  background:#fff;
  color:#17313f;
  border-color:#cbdbe2;
  box-shadow:inset 0 1px 0 rgba(34,68,85,.02)
}
.controls input::placeholder,.formula-controls input::placeholder,
.comparison-selectors input::placeholder,#workspaceSearch::placeholder{color:#8ca0aa}
.controls input:focus,.controls select:focus,
.formula-controls input:focus,.formula-controls select:focus,
.comparison-selectors select:focus,.comparison-selectors input:focus,
.research-tools textarea:focus,#workspaceSearch:focus,.evidence-controls select:focus{
  border-color:#3aa9b9;
  box-shadow:var(--focus);
