.detail-section{border-color:#e2e9ed}
.detail-section h4{color:#687f8b}
.detail-section p{color:#425f6d}
.tag{background:#eef7f9;color:#3a6f7c;border:1px solid #d7e9ed}
.relation,.timeline-card,.catalog-card,.tree-node,.lineage-chip,.tree-choice{
  background:#fff;
  border-color:#d9e4e9;
  color:#17313f;
  box-shadow:0 3px 12px rgba(45,76,92,.035);
  transition:border-color .16s ease,box-shadow .16s ease,transform .16s ease,background .16s ease
