  box-shadow:inset 3px 0 0 var(--accent),0 6px 18px rgba(14,143,163,.07)
}
.thought-tree-scroll{
  border-color:#dce6ea;
  background:linear-gradient(180deg,#fbfdff,#f5f9fb)
}
.tree-grid line,.tree-year-axis line{stroke:#dce6ea}
.tree-grid text,.tree-year-axis text,.tree-graph-year{fill:#758b96}
.tree-links path{stroke:#8aa6b4;stroke-opacity:.7}
.tree-graph-node circle{stroke:#fff;stroke-width:3;filter:drop-shadow(0 2px 3px rgba(35,67,83,.16))}
.tree-graph-node:hover circle{stroke:#0e8fa3}
.tree-graph-node.selected circle{stroke:#17313f}
.tree-graph-label{
  fill:#294858;
  font-weight:600;
  paint-order:stroke;
  stroke:#fff;
  stroke-width:3px;
  stroke-linejoin:round
}
.selected-lineage-panel,.formula-detail>div,.workspace-path{border-color:#e1e9ed}
.formula-card{
  border-color:#d9e4e9;
  background:#fff;
  box-shadow:0 5px 18px rgba(45,76,92,.05)
}
.formula-card h4{color:#17313f}
.formula-card p{color:#506c79}
.formula-meta{color:#0a8498;font-weight:650}
.formula-equation{
  background:linear-gradient(180deg,#f7fafc,#f3f8fa);
