/* Two-layer origin/development timeline — 2026-09-27 */
.timeline-head{align-items:flex-start}
.timeline-controls{display:grid;grid-template-columns:minmax(170px,1fr) minmax(190px,1.2fr);gap:10px;min-width:min(430px,48vw)}
.timeline-controls>div{min-width:0}
.timeline-controls label{display:block;font-size:10px;font-weight:750;color:var(--muted);margin:0 0 6px;text-transform:uppercase;letter-spacing:.06em}
.timeline-controls select{width:100%;height:40px;border:1px solid #cbdbe2;background:#fff;color:var(--text);border-radius:10px;padding:0 10px;outline:none}
.timeline-controls select:focus{border-color:#3aa9b9;box-shadow:var(--focus)}
.timeline-controls select:disabled{background:#f1f5f7;color:#91a1a9;cursor:not-allowed}
.timeline-card{position:relative}
